protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator", and direct SQL queries reference
        // c.Discriminator — preserve the old property name for data compatibility.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 no longer prefixes the discriminator in the JSON id property.
        // Existing documents have ids in "Product|123" format — preserve that format
        // so FindAsync and point-reads continue to work against existing data.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // REMOVED: HasIndex — EF Core 9 Cosmos provider now throws at startup for
    // HasIndex calls. Cosmos DB indexing is managed via the container's indexing
    // policy (Azure Portal / Bicep / Terraform), not through EF Core.
}

