using Microsoft.EntityFrameworkCore;

class CosmosQuery
{
    // EF Core 9 Cosmos provider no longer supports synchronous I/O —
    // ToList(), SaveChanges(), etc. now throw. Use async equivalents.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we configured
        // HasDiscriminator<string>("Discriminator") to preserve the old property name.
        // Without that opt-in, EF Core 9 would write "$type" instead and this query
        // would return zero results against existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

